package com.inventra.backend.controller; import com.inventra.backend.dto.*; import com.inventra.backend.service.WarehouseService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/warehouses") public class WarehouseController {private final WarehouseService s;public WarehouseController(WarehouseService s){this.s=s;}@PostMapping public WarehouseResponse create(@Valid @RequestBody WarehouseRequest r){return s.create(r);}@GetMapping public List<WarehouseResponse> all(){return s.all();}@GetMapping("/{id}") public WarehouseResponse get(@PathVariable String id){return s.getResponse(id);}}
